INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1ze411t7nb', 'course-bili-bv1ze411t7nb', '100001', '0', 'BILI-AI-GNR9GM', 'course-category-ai', 'instructor-bili-46880349', '【吴恩达团队Tensorflow2.0实践系列课程第一课】TensorFlow2.0中基于TensorFlow2.0的人工智能、机器学习和深度学习简介及基础编程', '25 讲完整课程 · 1 小时 15 分钟', '看此教学前请认真看完up的这段话： 1除开第一节视频和个别视频是官方英语字幕外，其余全为官方中字，2吴恩达团队前不久推出Tensorflow2.0系列课程在coursera上TF系列热度第一(他们的ML、DL', '课程简介：看此教学前请认真看完up的这段话： 1除开第一节视频和个别视频是官方英语字幕外，其余全为官方中字，2吴恩达团队前不久推出Tensorflow2.0系列课程在coursera上TF系列热度第一(他们的ML、DL应该都有了解，一直第一)，该系列有四门课，大家现在看到的是第一门（还有比如视觉、NLP、序列），看过他们团队或仅听说过的就能知道质量如何，跟着他们准没错。3视频为辅，他们为大家配备了专门的练习资料和阅读材料(jupyter中)，我也为大家下载好了。4关注点赞投币 课程结构：共 4 章 25 讲，累计时长 1 小时 15 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/21f27982bd365401b581d3fb8228f448780f8e67.jpg', '["人工智能","机器学习","大模型"]', 4537, 25, 38273, '4.4', 12673, 'BV1zE411T7nb', NULL, NULL, NULL, 1, 0, 'standard', NULL, '啥都会一点的研究生', 0, 'tenant', 'published', '2020-03-09T17:34:52.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
