    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1wmbpbpejj', 'course-bili-bv1wmbpbpejj', '100001', '0', 'BILI-AI-9XQRWN', 'course-category-ai', 'instructor-bili-3546814009576049', '2026大模型自然语言处理教程（NLP），从入门到实战系统精讲！存下吧，比啃书好太多了！', '99 讲完整课程 · 24 小时 51 分钟', '自然语言处理（NLP）是人工智能的核心领域，旨在让计算机理解、解释和生成人类语言。它融合了语言学与计算机科学，核心技术包括词法句法分析、情感分析、机器翻译和问答系统等。随着深度学习的发展，BERT、GPT等大模型极大', '课程简介：自然语言处理（NLP）是人工智能的核心领域，旨在让计算机理解、解释和生成人类语言。它融合了语言学与计算机科学，核心技术包括词法句法分析、情感分析、机器翻译和问答系统等。随着深度学习的发展，BERT、GPT等大模型极大地推动了NLP的进步，使其广泛应用于智能客服、搜索引擎、内容推荐等众多场景，是人机交互的关键技术。课程结构：共 13 章 99 讲，累计时长 24 小时 51 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/a5c12328aa3cfa9066e3df088a67e8920699446e.jpg', '["人工智能","机器学习","大模型","保姆级教程","NLP","比啃书好太多了！"]', 89474, 99, 3457, '4.4', 590, 'BV1WmBpBPEJJ', NULL, NULL, NULL, 1, 0, 'standard', NULL, '大模型研究所', 0, 'tenant', 'published', '2025-12-22T08:06:24.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
