    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-3079506', 'course-bili-season-3079506', '100001', '0', 'BILI-AI-1CCN2T', 'course-category-ai', 'instructor-bili-493192058', '30分钟入门强化学习机器人训练｜0基础也能会', '37 讲完整课程 · 12 小时 48 分钟', '这是一期四足机器人强化学习入门实操课，专门给零基础的小伙伴准备的～ 不用会建模、不用背公式、不用熟练操作专业软件，跟着我半小时上手，一步步教你写URDF文件、配置Isaac Gym和Legged Gym框架，完成强化学习', '课程简介：这是一期四足机器人强化学习入门实操课，专门给零基础的小伙伴准备的～ 不用会建模、不用背公式、不用熟练操作专业软件，跟着我半小时上手，一步步教你写URDF文件、配置Isaac Gym和Legged Gym框架，完成强化学习训练，让四足机器人成功实现强化学习自主行走仿真。后续我还会持续更新，拆解仿真到实物部署的全流程，汇总主流强化学习框架，带来更多机器人强化学习实操内容，大家记得点赞、投币、收藏，关注灯哥开源，一起轻松学机器人！您的支持就是我持续做开源视频和教程视频的动力！～ #强化学习 #四足机器人 #菠萝狗 #LeggedGym #新手入门 #机器人实操 #开源项目 #大学生必看 #小白学机器人 课程结构：共 1 章 37 讲，累计时长 12 小时 48 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/e08891703d0c2804501646193d2b64f10134eb3c.jpg', '["人工智能","机器学习","大模型","0基础也能会"]', 46093, 37, 7809, '4.5', 2209, 'BV1kYo8BhEkN', NULL, NULL, NULL, 1, 0, 'standard', NULL, '灯哥开源', 0, 'tenant', 'published', '2026-04-24T04:00:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
