INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-3925306', 'course-bili-season-3925306', '100001', '0', 'BILI-AI-775WRG', 'course-category-ai', 'instructor-bili-12420432', '动手学习AI-LLM', '42 讲完整课程 · 20 小时 8 分钟', '本视频深入剖析RAG技术的进化之路，从传统RAG到 Agentic RAG的全面升级。视频中解读了一个我很喜欢的开源的企业级项目chatbox和Search-R1（下一视频），chatbox 的agentic RAG能力', '课程简介：本视频深入剖析RAG技术的进化之路，从传统RAG到 Agentic RAG的全面升级。视频中解读了一个我很喜欢的开源的企业级项目chatbox和Search-R1（下一视频），chatbox 的agentic RAG能力比我使用过的其他同类型产品更强。希望可以帮助大家解析大模型从"被动检索"转变为"主动决策"的机制，实现更精准的知识获取与应用。累计时长 20 小时 8 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/d30708b1001321c3d15051a59f7247a8e449eaa0.jpg', '["人工智能","机器学习","大模型","动手学习AI","LLM"]', 72484, 42, 8872, '4.6', 2907, 'BV1iLx6zRETu', '129.00', '206.40', 'CNY', 0, 0, 'standard', NULL, '袁朝发', 0, 'tenant', 'published', '2025-10-09T10:00:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
