    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1mbkrzqebr', 'course-bili-bv1mbkrzqebr', '100001', '0', 'BILI-AI-W69CNK', 'course-category-ai', 'instructor-bili-243057436', '2025 吴恩达机器学习 保姆级 AI 入门教程！从零基础到实战', '151 讲完整课程 · 23 小时 7 分钟', '全系列覆盖吴恩达机器学习课程核心内容，从 "机器学习定义" 到 "实战项目" 全程中配，告别字幕障碍，零基础也能轻松跟学！涵盖监督学习、无监督学习、神经网络等经典模块，适合大学生、职场人系统提升 AI 技能。', '课程简介：全系列覆盖吴恩达机器学习课程核心内容，从 "机器学习定义" 到 "实战项目" 全程中配，告别字幕障碍，零基础也能轻松跟学！涵盖监督学习、无监督学习、神经网络等经典模块，适合大学生、职场人系统提升 AI 技能。吴恩达经典课程全新中配版，结合AI前沿案例（如大模型应用、自动化数据分析），通过 "理论讲解 + 代码实操" 双线教学，让你从零掌握机器学习核心逻辑，为深度学习、AI 算法岗打下扎实基础！课程结构：共 19 章 151 讲，累计时长 23 小时 7 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/6d4fbe8758f04a40962db4af120544a9d34d0fb3.png', '["人工智能","机器学习","大模型","中文配音","吴恩达机器学习","保姆级"]', 83233, 151, 64280, '4.2', 3752, 'BV1MBKRzqEBR', '129.00', '206.40', 'CNY', 0, 0, 'standard', NULL, '外影译坊', 0, 'tenant', 'published', '2025-06-26T06:12:46.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
