INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1wcpmzpemr', 'course-bili-bv1wcpmzpemr', '100001', '0', 'BILI-AI-HGMLXQ', 'course-category-ai', 'instructor-bili-3546884090104525', '人工智能入门基础教程，涵盖机器学习、深度学习、计算机视觉、自然语言处理全程通俗易懂，小白也能轻松学会！！Python/项目实战', '92 讲完整课程 · 24 小时 32 分钟', '【视频配套籽料、学习路线、GitHub项目、实战案例集、电子书+问题解答请看 "置顶平论" 自取哦】 本合集是一套从 0 到 1 的Python 机器学习实战课程，从环境配置、Python 语法、Pandas/Numpy', '课程简介：【视频配套籽料、学习路线、GitHub项目、实战案例集、电子书+问题解答请看 "置顶平论" 自取哦】 本合集是一套从 0 到 1 的Python 机器学习实战课程，从环境配置、Python 语法、Pandas/Numpy/Matplotlib 基础，到线性回归、逻辑回归、Kmeans、决策树、主成分分析等经典算法，再到多层感知器（MLP）、CNN、RNN、LSTM、迁移学习等深度学习内容，全程以实战项目驱动学习。课程包含少样本苹果分类、RNN 股价预测、LSTM 文本生成、迁移学习等多个真实案例，帮你从理论落地到工程实践，系统掌握机器学习与深度学习的核心能力，适合零基础入门或进阶提升。如果视频对你有用的话请 一键三连【长按点赞】支持一下UP哦，这对我真的很重要！课程结构：共 12 章 92 讲，累计时长 24 小时 32 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/28b5217feced6d6571831306b0d5c03fdd6a2007.jpg', '["人工智能","机器学习","大模型","人工智能入门基础教程","涵盖机器学习","深度学习"]', 88358, 92, 4985, '4.4', 763, 'BV1wCPmzPEmr', '129.00', '206.40', 'CNY', 0, 0, 'standard', NULL, '机器学习-ML', 0, 'tenant', 'published', '2026-03-09T03:06:53.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
