INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-8156346', 'course-bili-season-8156346', '100001', '0', 'BILI-AI-NQ3MNR', 'course-category-ai', 'instructor-bili-2061186491', '人工智能-大模型', '95 讲完整课程 · 1729 小时 5 分钟', '从神经网络的基础直觉出发，带你一步步走进深度学习与大型语言模型的核心地带。这个系列以可视化方式拆解了神经元、层与激活函数，让抽象概念变得清晰可感。通过手写数字识别任务，你会看到梯度下降如何驱动网络从随机猜测走向精', '课程简介：从神经网络的基础直觉出发，带你一步步走进深度学习与大型语言模型的核心地带。这个系列以可视化方式拆解了神经元、层与激活函数，让抽象概念变得清晰可感。通过手写数字识别任务，你会看到梯度下降如何驱动网络从随机猜测走向精准判断，并理解损失函数的实际意义。反向传播部分则用直观比喻和链式法则双线并行，既降低了对数学的畏惧，又保留了必要的推导深度，帮助建立扎实的优化思维。后半程转向前沿话题，先以精炼方式概览大型语言模型，再深入Transformer架构，把自注意力、多头注意力与交叉注意力机制逐一展开，让人看清模型如何捕捉上下文关系。多层感知机被形象地比作AI的记忆模块，揭示了事实存储的内在逻辑。最后延伸到图像与视频生成，补全了从判别到生成的认知拼图。无论你是刚接触AI的爱好者，还是希望夯实原理的从业者，都能在循序渐进的内容中找到属于自己的节奏。课程结构：共 1 章 95 讲，累计时长 1729 小时 5 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/f90a35ccc2de1171fff8bbd4889f0f59eaef7f00.jpg', '["人工智能","机器学习","大模型"]', 6224740, 95, 1074, '4.7', 525, 'BV1TxNs6cEG3', NULL, NULL, NULL, 1, 0, 'standard', NULL, '名校课程-顶级中配', 0, 'tenant', 'published', '2026-07-11T10:00:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
