    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1t7h76cecm', 'course-bili-bv1t7h76cecm', '100001', '0', 'BILI-AI-WSZ6TQ', 'course-category-ai', 'instructor-bili-3493286079630311', '机器学习全套教程（268集）从入门到实战，回归算法、聚类算法、决策树、随机森林、神经网络、贝叶斯算法、支持向量机等十大机器学习算法一口气学完！', '191 讲完整课程 · 47 小时 40 分钟', '课件代码留言区自取，本机器学习课程从基础算法讲起，涵盖回归、分类、聚类与模型评估，配合 Python 代码实战，理清原理与落地思路，帮你夯实 AI 基础，开启人工智能项目开发。', '课程简介：课件代码留言区自取，本机器学习课程从基础算法讲起，涵盖回归、分类、聚类与模型评估，配合 Python 代码实战，理清原理与落地思路，帮你夯实 AI 基础，开启人工智能项目开发。课程结构：共 24 章 191 讲，累计时长 47 小时 40 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/19a3474328809119c781b77997023e70658faaf8.jpg', '["人工智能","机器学习","大模型","2027新编版","机器学习全套教程","268集"]', 171627, 191, 777, '4.3', 102, 'BV1t7h76CECm', NULL, NULL, NULL, 1, 0, 'standard', NULL, '疯狂水论文', 0, 'tenant', 'published', '2026-09-22T07:42:35.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
