    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv14rgc67euw', 'course-bili-bv14rgc67euw', '100001', '0', 'BILI-AI-QFG24E', 'course-category-ai', 'instructor-bili-316220314', '大模型训练必要3天NLP极速入门自然语言处理', '40 讲完整课程 · 8 小时 51 分钟', '拒绝冗长晦涩的课本理论，不讲无用数学公式，零基础也能跟上。从文本预处理、词向量，到文本分类、情感分析、大模型基础应用，传统 NLP 与预训练模型干货一次性打通。配套完整可运行 Python 代码，跟着敲就能跑出效果。', '课程简介：拒绝冗长晦涩的课本理论，不讲无用数学公式，零基础也能跟上。从文本预处理、词向量，到文本分类、情感分析、大模型基础应用，传统 NLP 与预训练模型干货一次性打通。配套完整可运行 Python 代码，跟着敲就能跑出效果。学完能够独立搭建小型文本处理项目，适合在校生、想转型 AI、想要拓展技能的朋友。持续更新实战案例，视频干货满满！如果内容对你有帮助，点赞投币收藏一键三连，关注不迷路，一起走进自然语言处理！课程结构：共 5 章 40 讲，累计时长 8 小时 51 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/d264ad34e970747b9dbb15c36ff53cc07a242b50.jpg', '["人工智能","机器学习","大模型"]', 31900, 40, 63, '4.4', 12, 'BV14rGc67EuW', NULL, NULL, NULL, 1, 0, 'standard', NULL, '光哥编程课', 0, 'tenant', 'published', '2026-07-31T04:11:22.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
