    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-6799592', 'course-bili-season-6799592', '100001', '0', 'BILI-AI-ESJSEP', 'course-category-ai', 'instructor-bili-3546710972303532', '🔥【2026 LangChain 实战教程】从 0 到 1 入门进阶！手把手构建 AI 应用，打通 Agent 开发全流程', '21 讲完整课程 · 44 小时 14 分钟', '🚀 LangChain 入门到项目实战完整教程｜从零掌握 AI 应用开发！想系统学习 LangChain，却不知道从哪里入手？本教程从基础概念出发，逐步深入核心原理与项目实战，带你掌握大模型应用开发的关键技术，', '课程简介：🚀 LangChain 入门到项目实战完整教程｜从零掌握 AI 应用开发！想系统学习 LangChain，却不知道从哪里入手？本教程从基础概念出发，逐步深入核心原理与项目实战，带你掌握大模型应用开发的关键技术，构建从 LLM 调用到 RAG、AI Agent 的完整知识体系。🔥 课程核心内容 LangChain 基础入门：了解核心概念、框架组成与基本使用方法。核心原理解析：掌握 Prompt、Model、Output Parser、Chain 等核心组件。大模型应用开发：学习模型接入、提示词管理与结构化输出。RAG 检索增强生成：理解文档加载、文本切分、向量检索与知识库问答。AI Agent 智能体开发：掌握工具调用、任务执行与智能体应用构建。项目实战落地：整合 LangChain 核心能力，开发具备实际应用价值的 AI 项目。🎯 适合人群 前端工程师、全栈开发者、Python 开发者，以及希望进入 AI 应用开发领域的技术人员。💡 学习目标：从理解 LangChain，到独立构建 AI 应用。不止学会调用大模型，更要掌握 RAG、Agent 与应用工程化的核心思路，逐步提升 AI 全栈开发能力。持续分享 LangChain、AI Agent、大模型应用、前端工程化与全栈开发实战干货！课程结构：共 1 章 21 讲，累计时长 44 小时 14 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/6e98b3cf5b83442464ba3138575780c8bb656493.jpg', '["人工智能","机器学习","大模型","🔥","LangChain","实战教程"]', 159260, 21, 70, '4.3', 15, 'BV1Ghnn6NEsX', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'langchain__', 0, 'tenant', 'published', '2026-10-19T07:27:34.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
