INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-3758015', 'course-bili-season-3758015', '100001', '0', 'BILI-AI-N0NVNA', 'course-category-ai', 'instructor-bili-22215525', '星瞳科技OpenMV视频教程42-训练神经网络目标检测实际道路环境交通标志', '76 讲完整课程 · 13 小时 44 分钟', '本系列教程为OpenMV智能摄像头机器视觉模块的视频教程，由星瞳科技发布。OpenMV最新最酷炫的AI目标检测功能来啦！快来和我们星瞳科技的北大主播小姐姐一起来实现OpenMV自行训练神经网络目标点检测，识别实际复杂', '课程简介：本系列教程为OpenMV智能摄像头机器视觉模块的视频教程，由星瞳科技发布。OpenMV最新最酷炫的AI目标检测功能来啦！快来和我们星瞳科技的北大主播小姐姐一起来实现OpenMV自行训练神经网络目标点检测，识别实际复杂道路环境中的交通标志吧~！不仅支持OpenMV4 H7 Plus，同样支持OpenMV4 H7喔！训练出来的神经网络目标检测的模型F1 Score得分高达93%，运行帧率12帧~ 你可以根据此教程使用OpenMV自行训练检测任何你想要识别的物体或者目标，并且得到目标的坐标位置、数量等，对物体的远近大小或者角度都没有限制，累计时长 13 小时 44 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/3d6cf539cc79fcf046c2cb6235c6c59260cf6a9a.jpg', '["人工智能","机器学习","大模型"]', 49441, 76, 7008, '4.3', 497, 'BV1Qr4y177xi', NULL, NULL, NULL, 1, 0, 'standard', NULL, '网红小智智-星瞳OpenMV', 0, 'tenant', 'published', '2022-07-07T06:19:03.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
