    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-8258729', 'course-bili-season-8258729', '100001', '0', 'BILI-AI-UJVF41', 'course-category-ai', 'instructor-bili-2061186491', 'AI Agent全栈开发', '21 讲完整课程 · 144 小时 55 分钟', '从理解什么是深度智能体开始，这套内容会带你一步步走进用 LangChain 构建高级智能系统的完整流程。先理清核心概念，再直接进入项目实现，让你在搭建过程中真正体会深度智能体如何思考、规划和执行任务。接着会专门讲解如何利', '课程简介：从理解什么是深度智能体开始，这套内容会带你一步步走进用 LangChain 构建高级智能系统的完整流程。先理清核心概念，再直接进入项目实现，让你在搭建过程中真正体会深度智能体如何思考、规划和执行任务。接着会专门讲解如何利用 LangChain 灵活定制智能体行为，并横向对比不同工具链的差异，帮助你建立选型视野。随后深入到后端架构设计、上下文工程与记忆机制，这三者决定了智能体在长对话与复杂任务里的稳健性。还会展开讲解技能封装和子智能体的协同模式，让你能够设计出可扩展、可复用的多智能体方案。最后用一个端到端的综合项目把之前所有知识点串起来，从需求分析到上线交付，体验一次完整的开发闭环。整套内容节奏紧凑，三小时左右就能建立起系统化认知，既适合对自动化人工智能代理感兴趣的初学者快速入门，也适合有编程基础的开发者补齐工程落地能力，尤其推荐给正在用大语言模型做应用设计的技术人员。课程结构：共 1 章 21 讲，累计时长 144 小时 55 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/e2226d48940e5c297655e0c9f14f41ac00594ebb.jpg', '["人工智能","机器学习","大模型","AI","Agent全栈开发"]', 521754, 21, 344, '4.3', 78, 'BV16PEo6rEZo', NULL, NULL, NULL, 1, 0, 'standard', NULL, '名校课程-顶级中配', 0, 'tenant', 'published', '2026-06-11T06:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
