INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-8110961', 'course-bili-season-8110961', '100001', '0', 'BILI-AI-TF5Z1E', 'course-category-ai', 'instructor-bili-1951832142', 'AI/人工智能/ LLM / AIGC', '59 讲完整课程 · 844 小时 50 分钟', '您将学到什么： RAG流水线如何从头到尾工作：分块、嵌入、向量搜索、查询重写、上下文注入和流生成 如何设计Go接口使得大型语言模型（LLM）、嵌入器和向量存储可以互换而不影响其余代码库 如何将LLM令牌流式传输到终端及通', '课程简介：您将学到什么： RAG流水线如何从头到尾工作：分块、嵌入、向量搜索、查询重写、上下文注入和流生成 如何设计Go接口使得大型语言模型（LLM）、嵌入器和向量存储可以互换而不影响其余代码库 如何将LLM令牌流式传输到终端及通过Server-Sent Events到浏览器 如何对OpenAI,Ollama,LM Studio或Groq运行所有内容——以及如何混合搭配使用（例如，使用本地嵌入的托管聊天） 如何在生产环境中使用Postgres + pgvector进行向量搜索，包括HNSW索引和嵌入维度迁移 如何使用fsnotify以反应方式摄取文档，对未完成文件进行去抖动处理，并实现幂等重新摄取 如何处理多模态内容：图像上传、视觉模型字幕生成以及在聊天中渲染图像 如何调试"为什么模型没有使用我的文档？" -这门课程的不同之处在于： -实际可用的代码，而非伪代码。课程中的每一个示例都来自于一个可运行的工作项目。-首选本地化。您可以在笔记本电脑上使用Ollama完成整个课程，无需API费用。-对权衡持开放态度。课程讨论了已知的局限性（如分块器不考虑令牌、删除后再插入不是事务性的、图像检索基于描述），使您了解设计空间，而不仅仅是一个固定答案。技术栈包括：Go,Postgres 18,pgvector,Docker Compose,chi路由器,Tailwind,课程结构：共 1 章 59 讲，累计时长 844 小时 50 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/9f94990c2d12d65fff6766cf96c5d55da7adf4ee.jpg', '["人工智能","机器学习","大模型","AI","LLM"]', 3041405, 59, 170, '4.4', 63, 'BV1Xvnw6UEWL', '199.00', '318.40', 'CNY', 0, 0, 'standard', NULL, '常青藤中英字幕课', 0, 'tenant', 'published', '2026-10-20T06:01:49.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
