INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-6552495', 'course-bili-season-6552495', '100001', '0', 'BILI-AI-RQ00WT', 'course-category-ai', 'instructor-bili-450707179', '从零开始构建React智能代理：LangChain实战教程', '49 讲完整课程 · 33 小时 55 分钟', '从零开始构建React智能代理：LangChain实战教程。共 49 讲，累计 33.9 小时，由 AIDeepCoder 讲解，章节结构完整，可直接在课程播放器中观看。', '讲师先创建了虚拟环境，安装了必要的依赖包，比如langchain、langchain-community，还有谷歌的生成式AI模型Gemini，因为它免费，适合更多人学习。他演示了如何调用大模型生成内容，比如让模型讲个关于猫的冷知识。但很快指出：大模型只是"大脑"，没法访问实时信息。比如问"今天班加罗尔天气怎么样"，模型只能凭空编造答案——这就是所谓的"幻觉"。为了解决这个问题，就得给模型配上"工具"。于是他引入了Tavily搜索工具，让Agent能上网查真实数据。他还展示了Agent是怎么工作的：遵循"思考→行动→观察"的循环。比如先想"我得查一下天气"，然后调用搜索工具，拿到结果后再写一条真实的搞笑推文。不过问题来了：如果只给搜索工具，当问题需要当前时间（比如"SpaceX最近一次发射是多少天前？Agent就会卡住，甚至幻想出一个不存在的"计算天数"工具，导致无限循环。讲师又自己写了一个获取系统时间的自定义工具，并用@tool装饰器注册到Agent里。Agent就能结合多个工具解决问题：先搜发射日期，再拿当前时间计算间隔，最终给出准确答案。整个过 课程结构：共 1 章 49 讲，累计时长 33 小时 55 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["理解机器学习与深度学习核心算法背后的数学直觉","掌握 PyTorch / TensorFlow 训练、评估与调优的完整流程","完成从数据处理到模型部署的端到端实战项目","建立大模型与 Agent 应用的技术选型能力"]', '["有 Python 基础的开发者","希望转向算法与 AI 工程方向的从业者","需要落地 AI 能力的产品与研发团队"]', '["掌握 Python 基础语法","了解线性代数与概率论的基本概念"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/d59a393af1eed8f1bb20fce89fd2c3a8b7be3564.jpg', '["人工智能","机器学习","大模型"]', 122120, 49, 187, '4.3', 36, 'BV16J4XzeECV', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'AIDeepCoder', 0, 'tenant', 'published', '2025-10-17T12:05:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
